import itertools

def compile_target(target: dict) -> dict:
    if not isinstance(target, dict):
        return {"error": "Target must be a dict", "status": "refused"}
    if target.get("family") != "covering_design":
        return {"error": "Invalid family", "status": "refused"}
    params = target.get("params")
    if not isinstance(params, dict):
        return {"error": "Missing params", "status": "refused"}
    v = params.get("v")
    k = params.get("k")
    t = params.get("t")
    if not (isinstance(v, int) and isinstance(k, int) and isinstance(t, int)):
        return {"error": "Params v, k, t must be integers", "status": "refused"}
    if not (v > k and k >= t and t >= 1):
        return {"error": f"Invalid params relationship v={v}, k={k}, t={t}", "status": "refused"}
    blocks = target.get("blocks")
    if not isinstance(blocks, list) or len(blocks) == 0:
        return {"error": "Missing or empty blocks", "status": "refused"}

    new_v = v + 1
    new_k = k + 1
    new_t = t
    new_blocks = []

    for b in blocks:
        if not isinstance(b, list) or len(b) != k:
            return {"error": "Invalid block structure in target", "status": "refused"}
        if any(not isinstance(x, int) or x < 0 or x >= v for x in b):
            return {"error": "Block element out of range", "status": "refused"}
        if len(set(b)) != k:
            return {"error": "Block contains duplicates", "status": "refused"}
        new_blocks.append(sorted(b + [v]))

    return {
        "family": "covering_design",
        "params": {
            "v": new_v,
            "k": new_k,
            "t": new_t
        },
        "blocks": new_blocks,
        "provenance": {
            "compiler_id": "G1-COVERING-LIFT-V1",
            "input_case_id": target.get("caseId", "unknown"),
            "transformation": "point_extension_v_plus_1"
        },
        "claimBoundary": "Constructive lifting of C(v,k,t) to C(v+1,k+1,t) preserving block count."
    }

