import itertools

def verify_compilation(source: dict, candidate: dict) -> dict:
    errors = []
    if not isinstance(candidate, dict):
        return {"passed": False, "errors": ["Candidate must be a dictionary"]}
    if candidate.get("family") != "covering_design":
        errors.append("Candidate family must be covering_design")

    params = candidate.get("params")
    if not isinstance(params, dict):
        errors.append("Candidate params missing or not dict")
        v_cand = k_cand = t_cand = None
    else:
        v_cand = params.get("v")
        k_cand = params.get("k")
        t_cand = params.get("t")
        if not (isinstance(v_cand, int) and isinstance(k_cand, int) and isinstance(t_cand, int)):
            errors.append("v, k, t in candidate params must be integers")
        elif not (v_cand > k_cand and k_cand >= t_cand and t_cand >= 1):
            errors.append(f"Invalid candidate parameters: v={v_cand}, k={k_cand}, t={t_cand}")

    if isinstance(source, dict) and isinstance(source.get("params"), dict):
        sp = source["params"]
        if isinstance(v_cand, int) and isinstance(sp.get("v"), int) and v_cand <= sp["v"]:
            errors.append("Candidate v must be strictly greater than source v")
        if isinstance(k_cand, int) and isinstance(sp.get("k"), int) and k_cand <= sp["k"]:
            errors.append("Candidate k must be strictly greater than source k")
        if isinstance(t_cand, int) and isinstance(sp.get("t"), int) and t_cand != sp["t"]:
            errors.append("Candidate t must equal source t")

    blocks = candidate.get("blocks")
    if not isinstance(blocks, list):
        errors.append("Candidate blocks must be a list")
    else:
        if isinstance(source, dict) and isinstance(source.get("blocks"), list):
            if len(blocks) != len(source["blocks"]):
                errors.append(f"Block count mismatch: candidate has {len(blocks)}, source has {len(source['blocks'])}")
        if isinstance(v_cand, int) and isinstance(k_cand, int) and isinstance(t_cand, int) and not errors:
            block_sets = []
            for idx, b in enumerate(blocks):
                if not isinstance(b, list):
                    errors.append(f"Block {idx} is not a list")
                    continue
                if len(b) != k_cand:
                    errors.append(f"Block {idx} length is {len(b)}, expected {k_cand}")
                if len(set(b)) != len(b):
                    errors.append(f"Block {idx} contains duplicate elements")
                for elem in b:
                    if not isinstance(elem, int) or elem < 0 or elem >= v_cand:
                        errors.append(f"Block {idx} element {elem} out of range [0, {v_cand - 1}]")
                block_sets.append(set(b))
            if not errors:
                uncovered = []
                for t_tuple in itertools.combinations(range(v_cand), t_cand):
                    t_set = set(t_tuple)
                    if not any(t_set.issubset(bs) for bs in block_sets):
                        uncovered.append(t_tuple)
                        if len(uncovered) >= 3:
                            break
                if uncovered:
                    errors.append(f"Uncovered {t_cand}-subsets found, e.g. {uncovered}")

    return {"passed": len(errors) == 0, "errors": errors}
